-- 0023_users_v2 (design v2, N4): profile fields and one-time passwords of
-- local accounts, and the e-mail address of SSO/proxy users seen at sign-in.
-- created_at 0 and created_by '' mean "unknown" (accounts older than this).
ALTER TABLE local_users ADD COLUMN display_name TEXT NOT NULL DEFAULT '';
ALTER TABLE local_users ADD COLUMN email TEXT NOT NULL DEFAULT '';
-- A one-time password (generated by an admin) is valid until this time
-- (unix ms); 0 = the password is not a one-time password.
ALTER TABLE local_users ADD COLUMN otp_expires_at INTEGER NOT NULL DEFAULT 0;
ALTER TABLE local_users ADD COLUMN created_at INTEGER NOT NULL DEFAULT 0;
ALTER TABLE local_users ADD COLUMN created_by TEXT NOT NULL DEFAULT '';
ALTER TABLE principals ADD COLUMN email TEXT NOT NULL DEFAULT '';
